class Solution {
    public int findDuplicate(int[] nums) {
        int slow = nums[0];
        int fast = nums[0];

        do {
            slow = nums[slow];
            fast = nums[nums[fast]];
        } while (slow != fast);

        slow = nums[0];
        while (slow != fast) {
            slow = nums[slow];
            fast = nums[fast];
        }

        return slow;
    }
}

class Solution {
    public int findDuplicate(int[] nums) {
        int left = 1;
        int right = nums.length - 1;

        while (left < right) {
            int mid = left + (right - left) / 2;
            int count = 0;
            for (int num : nums) {
                if (num <= mid) {
                    count++;
                }
            }

            if (count > mid) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }
}

class Solution {
    public int findDuplicate(int[] nums) {
        int n = nums.length - 1;
        int duplicate = 0;

        for (int bit = 0; bit < 31; bit++) {
            int mask = 1 << bit;
            int expected = 0;
            int actual = 0;

            for (int value = 1; value <= n; value++) {
                if ((value & mask) != 0) {
                    expected++;
                }
            }
            for (int num : nums) {
                if ((num & mask) != 0) {
                    actual++;
                }
            }

            if (actual > expected) {
                duplicate |= mask;
            }
        }

        return duplicate;
    }
}

import java.util.*;

class Solution {
    public int findDuplicate(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int num : nums) {
            if (!seen.add(num)) {
                return num;
            }
        }
        return -1;
    }
}
